            rich_opp += 1
        if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
            urgent_opp += 1
        prev = opp.get('previous_trace', {})
        bid = prev.get('bid') if prev else None
        if bid is not None:
            prev_bids.append(float(bid))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    guaranteed_units = int(supply // WATER_REQ)

    danger = 0
    if hp <= 2:
        danger += 3
    elif hp <= 4:
        danger += 2
    elif hp <= 6:
        danger += 1
    if no_water_days >= 2:
        danger += 3
    elif no_water_days >= 1:
        danger += 2

    if guaranteed_units >= 2:
        base = 48.0
        if danger >= 4:
            base = 74.0
        elif danger >= 2:
            base = 62.0

        target = max(base, avg_prev + 2.0)
        if urgent_opp >= 2:
            target += 4.0
        if rich_opp >= 2:
            target += 2.0
        if budget < 250:
            target -= 6.0
        return float(max(0.0, min(budget, target)))

    base = 22.0
    if danger >= 5:
        base = 86.0
    elif danger >= 3:
        base = 73.0
    elif danger >= 1:
        base = 58.0

    if highest_prev >= 95.0 and danger <= 2:
        target = 18.0
    elif highest_prev >= 80.0 and danger <= 1:
        target = 24.0
    else:
        if danger >= 3:
            target = max(base, highest_prev + 1.6)
        else:
            target = min(base, highest_prev + 0.5) if highest_prev > 0 else base

    if day >= 8 and hp >= 6 and danger <= 1:
        target *= 0.8
    if budget < 180:
        target = min(target, 52.0)
    if budget < 120:
        target = min(target, 38.0)

    return float(max(0.0, min(budget, target)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    # Identify alive opponents and extract yesterday bids
    alive_opps = []
    yesterday_bids = []
    for oid, o in opponents_status.items():
        if o.get('alive'):
            alive_opps.append(o)
            prev = o.get('previous_trace', {}) or {}
            b = prev.get('bid', None)
            if b is not None:
                try:
                    yesterday_bids.append(float(b))
                except Exception:
                    pass

    # If no alive opponents, bid conservatively
    if not alive_opps:
        return max(0.0, min(float(my_status['budget']), DAILY_SALARY * 0.4))

    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    # React to yesterday's maximum pressure
    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0

    # Base target: ensure some chance at getting water when supply is near/above requirement
    # With supply in [15,25], water allocation likely depends on relative bids.
    # We choose a mid-high bid to beat typical opponents without matching the top bidder.
    if hp <= 2 or no_water_days >= 2:
        # Critical: spend to secure water
        target = DAILY_SALARY * 0.9
    else:
        # Non-critical: adjust based on observed pressure
        if highest_prev_bid >= DAILY_SALARY * 0.85:
            # Someone was bidding very aggressively; counter with strong but not maximum
            target = min(DAILY_SALARY * 0.75, highest_prev_bid * 0.85)
        else:
            # Typical pressure: bid enough to stay competitive
            target = max(DAILY_SALARY * 0.55, highest_prev_bid * 0.7)

    # Scale slightly with supply: higher supply reduces need for extreme bidding
    # supply ~15 => more scarce; supply ~25 => less scarce
    scarcity = (MAX_SUPPLY - supply) / (MAX_SUPPLY - MIN_SUPPLY)  # 0..1
    target = target * (0.9 + 0.2 * scarcity)

    # Budget cap
    bid = min(budget, target)

    # Ensure non-negative
    if bid < 0:
        bid = 0.0

    return float(bid)

